import { createServer } from "node:http";
import { DEFAULT_DEV_SHELL_PORT } from "./ports.js";
/** The only listening server in a run. Vite upgrade targets never listen. */
export class SharedServer {
    routes = new Map();
    server = createServer((req, res) => {
        const route = this.routes.get(this.hostname(req.headers.host));
        if (route) {
            route.handle(req, res);
        }
        else {
            res.writeHead(404);
            res.end("Unknown dev shell hostname");
        }
    });
    sockets = new Set();
    port = 0;
    constructor() {
        this.server.on("connection", socket => {
            this.sockets.add(socket);
            socket.on("close", () => this.sockets.delete(socket));
        });
        this.server.on("upgrade", (req, socket, head) => {
            const route = this.routes.get(this.hostname(req.headers.host));
            if (!route?.upgrades?.emit("upgrade", req, socket, head)) {
                socket.destroy();
            }
        });
    }
    hostname(host) {
        return (host ?? "").split(":")[0].toLowerCase();
    }
    async listen(port = DEFAULT_DEV_SHELL_PORT, strict = false) {
        for (;;) {
            try {
                await new Promise((resolve, reject) => {
                    const onError = (error) => {
                        this.server.off("listening", onListening);
                        reject(error);
                    };
                    const onListening = () => {
                        this.server.off("error", onError);
                        resolve();
                    };
                    this.server.once("error", onError);
                    this.server.once("listening", onListening);
                    this.server.listen(port, "127.0.0.1");
                });
                this.port = this.server.address().port;
                return this.port;
            }
            catch (error) {
                if (error.code !== "EADDRINUSE") {
                    throw error;
                }
                if (strict || port === 65535) {
                    throw new Error(`Port ${port} is already in use. Stop the other server or choose --port <port>.`, { cause: error });
                }
                port++;
            }
        }
    }
    async close() {
        this.routes.clear();
        for (const socket of this.sockets) {
            socket.destroy();
        }
        await new Promise(resolve => this.server.close(() => resolve()));
    }
}
